from pathlib import Path
from datetime import datetime
import re
import sqlite3


TARGET_RESOLUTION_ID = "RES-25Q1-0408-03"
PROJECT_ID = "PRJ_LAB_TAT_2025Q1"
QUALITY_OFFICE_ACTOR_ID = "EMP_LIN_SUINING"
TRAP_RESOLUTION_IDS = ("RES-25Q1-0408-T1", "RES-25Q1-0408-D1")


def _paths(ws):
    database = Path(ws).parent / "system" / "oa_quality_governance" / "state.db"
    baseline = database.with_name("state.db.pinned_backup")
    return database, baseline


def _connect(path):
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _project_resolution_ids(connection, final_only=False):
    clause = " AND r.resolution_type='final_action' AND r.final_flag=1" if final_only else ""
    rows = connection.execute(
        "SELECT r.resolution_id FROM meeting_resolutions r "
        "JOIN governance_meetings m ON m.meeting_id=r.meeting_id "
        "WHERE m.project_id=?" + clause + " ORDER BY r.resolution_id",
        (PROJECT_ID,),
    ).fetchall()
    return [row[0] for row in rows]


def _rows_by_ids(connection, table, key, ids):
    placeholders = ",".join("?" for _ in ids)
    return [
        tuple(row)
        for row in connection.execute(
            f"SELECT * FROM {table} WHERE {key} IN ({placeholders}) ORDER BY {key}", ids
        ).fetchall()
    ]


def _audit_ids(connection, resolution_ids):
    placeholders = ",".join("?" for _ in resolution_ids)
    return {
        row[0]
        for row in connection.execute(
            f"SELECT audit_id FROM approval_audit_trail WHERE resolution_id IN ({placeholders})",
            resolution_ids,
        ).fetchall()
    }


def _normalized(value):
    return re.sub(r"[\s\W_]+", "", (value or "").lower())


def check_formal_pda_resolution_escalated(ws):
    database, baseline = _paths(ws)
    if not database.exists() or not baseline.exists():
        return {"score": 0, "detail": "治理系统数据库或 pinned 基线缺失"}
    with _connect(database) as current, _connect(baseline) as before:
        current_row = current.execute(
            "SELECT * FROM meeting_resolutions WHERE resolution_id=?", (TARGET_RESOLUTION_ID,)
        ).fetchone()
        baseline_row = before.execute(
            "SELECT * FROM meeting_resolutions WHERE resolution_id=?", (TARGET_RESOLUTION_ID,)
        ).fetchone()
    if current_row is None or baseline_row is None:
        return {"score": 0, "detail": "目标正式决议在当前库或基线中缺失"}
    current_data = dict(current_row)
    baseline_data = dict(baseline_row)
    prior_status = baseline_data.pop("owner_confirmation_status")
    new_status = current_data.pop("owner_confirmation_status")
    if prior_status != "pending" or new_status != "escalated":
        return {
            "score": 0,
            "detail": f"目标状态应为 pending -> escalated，实际为 {prior_status} -> {new_status}",
        }
    if current_data != baseline_data:
        return {"score": 0, "detail": "目标状态虽变化，但原决议的其他业务字段被改动"}
    return {"score": 1, "detail": "正式PDA决议已由 pending 升级为 escalated，原决议字段未变"}


def check_quality_office_escalation_audit(ws):
    database, baseline = _paths(ws)
    if not database.exists() or not baseline.exists():
        return {"score": 0, "detail": "治理系统数据库或 pinned 基线缺失"}
    with _connect(database) as current, _connect(baseline) as before:
        baseline_ids = _audit_ids(before, [TARGET_RESOLUTION_ID])
        current_rows = current.execute(
            "SELECT * FROM approval_audit_trail WHERE resolution_id=? ORDER BY acted_at,audit_id",
            (TARGET_RESOLUTION_ID,),
        ).fetchall()
    new_rows = [row for row in current_rows if row["audit_id"] not in baseline_ids]
    if len(new_rows) != 1:
        return {"score": 0, "detail": f"目标决议应新增一条升级流水，实际新增 {len(new_rows)} 条"}
    row = new_rows[0]
    try:
        acted_at = datetime.fromisoformat(row["acted_at"])
    except (TypeError, ValueError):
        return {"score": 0, "detail": "新增流水的操作时间不可解析"}
    comment = _normalized(row["action_comment"])
    has_overdue = any(token in comment for token in ("逾期", "超过期限", "超过到期", "overdue"))
    has_pending_confirmation = any(
        token in comment for token in ("待责任确认", "责任确认仍未完成", "未完成责任确认", "未确认", "pending")
    )
    has_pda_action = ("pda" in comment or "m02" in comment or "采集后" in comment) and (
        "提醒" in comment or "25分钟" in comment or "30分钟" in comment or "上线" in comment
    )
    structural_ok = (
        row["document_type"] == "resolution_confirmation"
        and str(row["document_version"]).startswith("ESCALATE-V1")
        and row["document_version_status"] == "submitted"
        and row["audit_status"] == "submitted"
        and row["publish_flag"] == 0
        and row["actor_id"] == QUALITY_OFFICE_ACTOR_ID
        and acted_at.date().isoformat() > "2025-05-10"
    )
    if not structural_ok:
        return {"score": 0, "detail": f"新增流水的类型、发起人、状态或操作时间不符合升级要求: {dict(row)}"}
    if not (has_overdue and has_pending_confirmation and has_pda_action):
        return {"score": 0, "detail": "升级原因须语义说明PDA行动、逾期及责任确认仍未完成"}
    return {"score": 1, "detail": f"质量管理办公室已新增有效升级流水 {row['audit_id']}"}


def check_nonfinal_traps_unchanged(ws):
    database, baseline = _paths(ws)
    if not database.exists() or not baseline.exists():
        return {"score": 0, "detail": "治理系统数据库或 pinned 基线缺失"}
    with _connect(database) as current, _connect(baseline) as before:
        current_rows = _rows_by_ids(current, "meeting_resolutions", "resolution_id", TRAP_RESOLUTION_IDS)
        baseline_rows = _rows_by_ids(before, "meeting_resolutions", "resolution_id", TRAP_RESOLUTION_IDS)
        current_audits = _audit_ids(current, list(TRAP_RESOLUTION_IDS))
        baseline_audits = _audit_ids(before, list(TRAP_RESOLUTION_IDS))
    if current_rows != baseline_rows or current_audits != baseline_audits:
        return {"score": 0, "detail": "trap_summary 或 suggested_target 干扰记录被改动或新增了审计"}
    return {"score": 1, "detail": "汇总行和会前建议行保持基线不变"}


def check_other_project_actions_unchanged(ws):
    database, baseline = _paths(ws)
    if not database.exists() or not baseline.exists():
        return {"score": 0, "detail": "治理系统数据库或 pinned 基线缺失"}
    with _connect(database) as current, _connect(baseline) as before:
        baseline_ids = _project_resolution_ids(before, final_only=True)
        current_ids = _project_resolution_ids(current, final_only=True)
        other_ids = [resolution_id for resolution_id in baseline_ids if resolution_id != TARGET_RESOLUTION_ID]
        current_rows = _rows_by_ids(current, "meeting_resolutions", "resolution_id", other_ids)
        baseline_rows = _rows_by_ids(before, "meeting_resolutions", "resolution_id", other_ids)
        current_audits = _audit_ids(current, other_ids)
        baseline_audits = _audit_ids(before, other_ids)
    if current_ids != baseline_ids:
        return {"score": 0, "detail": "专项正式行动集合被增删"}
    if current_rows != baseline_rows or current_audits != baseline_audits:
        return {"score": 0, "detail": "目标之外的正式行动或其审计流水发生变化"}
    return {"score": 1, "detail": "其余四项正式行动及既有审计保持不变"}

