        row = con.execute(
            "SELECT authorization_id, premises_id, operation_code, effective_date, "
            "expiration_date, authorization_status, evidence_reference "
            "FROM permit_authorizations WHERE authorization_id = ?",
            (AUTHORIZATION,),
        ).fetchone()
    expected = (AUTHORIZATION, PREMISES, "PROCESS", "2025-08-15", None, "PENDING", "TTB-FILE-5100-24-2025-091")
    actual = tuple(row) if row else None
    if actual == expected:
        return {"score": 1, "detail": "Linked process authorization is unchanged and remains PENDING."}
    return {"score": 0, "detail": f"Linked authorization changed: expected {expected}, got {actual}."}


def check_other_loretto_amendments_unchanged(workspace):
    expected = {
        "AMD-DSP184-ADDRESS-2024": "APPROVED",
        "AMD-DSP184-EQUIP-2025": "FILED",
    }
    with _connect(workspace) as con:
        rows = con.execute(
            "SELECT amendment_id, case_status FROM amendment_cases "
            "WHERE amendment_id IN (?, ?) ORDER BY amendment_id",
            tuple(expected),
        ).fetchall()
    actual = {row["amendment_id"]: row["case_status"] for row in rows}
    if actual == expected:
        return {"score": 1, "detail": "Other Loretto amendments retain their pre-task statuses."}
    return {"score": 0, "detail": f"Other Loretto amendment statuses changed: expected {expected}, got {actual}."}
